window.kbPageData["views/entry/k-1ee6f6eb1f817403"] = {"key":"entry/k-1ee6f6eb1f817403","state":{"route":"entry/k-1ee6f6eb1f817403"},"node":{"id":"k-1ee6f6eb1f817403","mode":"k","title":"总消费额与人均消费额","type":"原理与机制","domain":"统计","reading":"","intro":"","priority":100,"aliases":["总消费额等于消费人数乘以人均消费额"],"qs":["江苏 2024 A类 行测#132"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"人均消费额是一定时期内某一统计人群的总消费额除以该人群人数所得的平均值。统计人群、时期和消费范围一致时，总消费额等于人数乘以人均消费额。","review":{"definition":"人均消费额是一定时期内某一统计人群的总消费额除以该人群人数所得的平均值。统计人群、时期和消费范围一致时，总消费额等于人数乘以人均消费额。","explanation":"第132题按表中直播电商行业的统计口径，用2021年用户数4.3亿人乘以人均年消费额4640元，估算该年交易额为19952亿元，即1.9952万亿元。以材料直接给出的2022年交易额3.5万亿元为前项，两年交易额之比约为3.5∶2，即7∶4，选D。","references":[],"evidence":"用户数为4.3亿人，人均年消费额为4640元","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2024 A类 行测#132":{"paper":"江苏 2024 A类 行测","n":132,"mod":"资料分析","src":["f8fec75f67d6d1ba5759.pdf",26],"asrc":["0126a1c8aceee632ea2b.pdf",40],"card":"68e7413732d667e132559714","links":[{"id":"k-1ee6f6eb1f817403","role":"解题依据","why":"2021年交易额由同口径的用户数和人均年消费额相乘得到。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-1ee6f6eb1f817403":[["江苏 2024 A类 行测#132"]]}};
